//! 32-bit secp256r1 base field implementation
//!
//! **Janus vendored change (rusty_esp_mid, round 3 of the optimization
//! campaign, 2026-10-01).** p256 0.13.2 shipped this file as the 64-bit
//! arithmetic behind a conversion ("TODO(tarcieri): adapt 64-bit arithmetic
//! to proper 32-bit arithmetic"): every multiply-accumulate was a 64x64-bit
//! product with a 128-bit sum, which a 32-bit CPU emulates. On an ESP32-S3
//! `fe_mul` compiled to 2,864 instructions. Here every operation is on the
//! eight 32-bit limbs the type already holds: a CIOS Montgomery multiply
//! (Koc, Acar, Kaliski 1996) using P-256's shape -- `-p^-1 mod 2^32` is 1,
//! and the modulus words are all-ones, zero or one -- and 32-bit carry
//! chains for the rest. The representation is unchanged (little-endian
//! limbs, Montgomery form with R = 2^256, fully reduced), and a fully
//! reduced Montgomery product is unique, so every result is the one the old
//! code returned; `tests::*_match_the_u64_reference` hold it to that code,
//! kept below as `reference`.

use super::R_2;

/// Raw field element.
pub type Fe = [u32; 8];

/// The modulus' limbs, little-endian: 2^256 - 2^224 + 2^192 + 2^96 - 1.
const P: Fe = [
    0xFFFF_FFFF,
    0xFFFF_FFFF,
    0xFFFF_FFFF,
    0,
    0,
    0,
    1,
    0xFFFF_FFFF,
];

/// `acc + a * b + carry` as (low, high) words. Cannot overflow 64 bits.
#[inline(always)]
const fn mac32(acc: u32, a: u32, b: u32, carry: u32) -> (u32, u32) {
    let w = (acc as u64) + (a as u64) * (b as u64) + (carry as u64);
    (w as u32, (w >> 32) as u32)
}

/// `a + b + carry` as (sum, carry), carry 0 or 1.
#[inline(always)]
const fn adc32(a: u32, b: u32, carry: u32) -> (u32, u32) {
    let w = (a as u64) + (b as u64) + (carry as u64);
    (w as u32, (w >> 32) as u32)
}

/// `a - b - borrow` where `borrow` is 0 or all-ones; the new borrow the
/// same way (all-ones when the subtraction went below zero).
#[inline(always)]
const fn sbb32(a: u32, b: u32, borrow: u32) -> (u32, u32) {
    let w = (a as u64).wrapping_sub((b as u64) + ((borrow >> 31) as u64));
    (w as u32, (w >> 32) as u32)
}

/// Nine limbs (the eighth carry on top) less the modulus when that does not
/// go below zero: the result in `[0, p)` for any input below `2p`.
#[inline(always)]
const fn sub_p(t: &[u32; 9]) -> Fe {
    let mut w = [0u32; 8];
    let mut borrow = 0u32;
    let mut j = 0;
    while j < 8 {
        let (s, b) = sbb32(t[j], P[j], borrow);
        w[j] = s;
        borrow = b;
        j += 1;
    }
    let (_, borrow) = sbb32(t[8], 0, borrow);
    // all-ones when t < p: add the modulus back
    let mut carry = 0u32;
    let mut j = 0;
    while j < 8 {
        let (s, c) = adc32(w[j], P[j] & borrow, carry);
        w[j] = s;
        carry = c;
        j += 1;
    }
    w
}

/// `fe_mul` in Xtensa asm (round 3): the same CIOS, every carry by `saltu`
