/// Translate a field element out of the Montgomery domain: `w * 1 / R`.
#[inline]
pub const fn fe_from_montgomery(w: &Fe) -> Fe {
    fe_mul(w, &[1, 0, 0, 0, 0, 0, 0, 0])
}

/// Translate a field element into the Montgomery domain.
#[inline]
pub const fn fe_to_montgomery(w: &Fe) -> Fe {
    fe_mul(w, R_2.as_words())
}

/// Returns `a + b mod p`.
pub const fn fe_add(a: &Fe, b: &Fe) -> Fe {
    let mut t = [0u32; 9];
    let mut carry = 0u32;
    let mut j = 0;
    while j < 8 {
        let (s, c) = adc32(a[j], b[j], carry);
        t[j] = s;
        carry = c;
        j += 1;
    }
    t[8] = carry;
    sub_p(&t)
}

/// Returns `a - b mod p`.
pub const fn fe_sub(a: &Fe, b: &Fe) -> Fe {
    let mut w = [0u32; 8];
    let mut borrow = 0u32;
    let mut j = 0;
    while j < 8 {
        let (s, bw) = sbb32(a[j], b[j], borrow);
        w[j] = s;
        borrow = bw;
        j += 1;
    }
    // all-ones when a < b: add the modulus
    let mut carry = 0u32;
    let mut j = 0;
    while j < 8 {
        let (s, c) = adc32(w[j], P[j] & borrow, carry);
        w[j] = s;
        carry = c;
        j += 1;
    }
    w
}

/// Returns `a * b mod p` (Montgomery: `a * b / R`).
///
/// CIOS, a limb of `b` a round. P-256's `-p^-1 mod 2^32` is 1, so a
/// round's reduction multiplier is just the low word, and adding
/// `m * p[0] = m * (2^32 - 1)` to it leaves 0 with `m` carried.
pub const fn fe_mul(a: &Fe, b: &Fe) -> Fe {
    #[cfg(janus_saltu)]
    {
        // the asm at runtime; this Rust at compile time (constants). The
        // two are the same function (tests, and the probe on the chip).
        core::intrinsics::const_eval_select((a, b), fe_mul_rust, fe_mul_xtensa)
    }
    #[cfg(not(janus_saltu))]
    {
        fe_mul_rust(a, b)
    }
}

/// The CIOS in Rust: every target's multiply, and Xtensa's at compile time.
const fn fe_mul_rust(a: &Fe, b: &Fe) -> Fe {
    let mut t = [0u32; 10];
    let mut i = 0;
    while i < 8 {
        let bi = b[i];
        let mut c = 0u32;
        let mut j = 0;
        while j < 8 {
            let (s, cc) = mac32(t[j], a[j], bi, c);
            t[j] = s;
            c = cc;
            j += 1;
        }
        let (s, cc) = adc32(t[8], c, 0);
        t[8] = s;
        t[9] = cc;

        // + m * p, shifted down a word. The modulus words are all-ones
        // (m * (2^32 - 1) = (m << 32) - m), zero or one, so the reduction
        // needs no multiply at all.
        let m = t[0];
        let m_ff = ((m as u64) << 32) - (m as u64);
        // p, little-endian: FF FF FF 0 0 0 1 FF (words 0..=7); word 0 is
        // the carry `m` below, words 1..=7 are the seven steps
        let w = (t[1] as u64) + m_ff + (m as u64); // word 0: t0 + m * 0xFFFF_FFFF = m << 32
        t[0] = w as u32;
        let w = (t[2] as u64) + m_ff + (w >> 32); // word 2
        t[1] = w as u32;
        let w = (t[3] as u64) + (w >> 32); // word 3: 0
        t[2] = w as u32;
        let w = (t[4] as u64) + (w >> 32); // word 4: 0
        t[3] = w as u32;
        let w = (t[5] as u64) + (w >> 32); // word 5: 0
        t[4] = w as u32;
        let w = (t[6] as u64) + (m as u64) + (w >> 32); // word 6: 1
        t[5] = w as u32;
        let w = (t[7] as u64) + m_ff + (w >> 32); // word 7: all ones
        t[6] = w as u32;
        let w = (t[8] as u64) + (w >> 32);
        t[7] = w as u32;
        t[8] = t[9] + (w >> 32) as u32;
        i += 1;
    }
    sub_p(&[t[0], t[1], t[2], t[3], t[4], t[5], t[6], t[7], t[8]])
}

/// Returns `-w mod p`.
pub const fn fe_neg(w: &Fe) -> Fe {
    fe_sub(&[0; 8], w)
}

/// Returns `w * w mod p` (Montgomery: `w^2 / R`).
///
/// SOS: the 512-bit square from 28 cross products (doubled) and 8 squares
/// -- 36 multiply-accumulates where `fe_mul` needs 64 -- then eight rounds
/// of the same multiply-free reduction `fe_mul` uses, each rippling its
/// carry up the high half.
pub const fn fe_square(a: &Fe) -> Fe {
    #[cfg(janus_saltu)]
    {
        core::intrinsics::const_eval_select((a,), fe_square_rust, fe_square_xtensa)
    }
    #[cfg(not(janus_saltu))]
    {
        fe_square_rust(a)
    }
}

/// `w * w` through the asm multiply (Xtensa, runtime).
#[cfg(janus_saltu)]
fn fe_square_xtensa(a: &Fe) -> Fe {
    fe_mul_xtensa(a, a)
}

/// The SOS square in Rust.
const fn fe_square_rust(a: &Fe) -> Fe {
    // t = sum over i < j of a_i a_j b^(i+j)
    let mut t = [0u32; 17];
    let mut i = 0;
    while i < 7 {
        let mut c = 0u32;
        let mut j = i + 1;
        while j < 8 {
            let (s, cc) = mac32(t[i + j], a[i], a[j], c);
            t[i + j] = s;
            c = cc;
            j += 1;
        }
        t[i + 8] = c;
        i += 1;
    }
    // t = 2t + sum a_i^2 b^(2i)
    let mut carry = 0u32;
    let mut k = 0;
    while k < 16 {
        let doubled = ((t[k] as u64) << 1) | (carry as u64);
        carry = (t[k] >> 31) as u32;
        t[k] = doubled as u32;
        k += 1;
    }
    let mut c = 0u32;
    let mut i = 0;
    while i < 8 {
        let (s, cc) = mac32(t[2 * i], a[i], a[i], c);
        t[2 * i] = s;
        let (s, cc2) = adc32(t[2 * i + 1], cc, 0);
        t[2 * i + 1] = s;
        c = cc2;
        i += 1;
    }
    t[16] = c;

    // eight rounds: t += m * p * b^i with m = t[i], which zeroes t[i]
    let mut i = 0;
    while i < 8 {
        let m = t[i];
        let m_ff = ((m as u64) << 32) - (m as u64);
        // words i+1 ..= i+7 of p: FF FF 0 0 0 1 FF; word i's m carried
        let w = (t[i + 1] as u64) + m_ff + (m as u64);
        t[i + 1] = w as u32;
        let w = (t[i + 2] as u64) + m_ff + (w >> 32);
        t[i + 2] = w as u32;
        let w = (t[i + 3] as u64) + (w >> 32);
        t[i + 3] = w as u32;
        let w = (t[i + 4] as u64) + (w >> 32);
        t[i + 4] = w as u32;
        let w = (t[i + 5] as u64) + (w >> 32);
        t[i + 5] = w as u32;
        let w = (t[i + 6] as u64) + (m as u64) + (w >> 32);
        t[i + 6] = w as u32;
        let w = (t[i + 7] as u64) + m_ff + (w >> 32);
        t[i + 7] = w as u32;
        // ripple the carry up through the high half
        let mut c = (w >> 32) as u32;
        let mut k = i + 8;
        while k < 17 {
            let (s, cc) = adc32(t[k], c, 0);
            t[k] = s;
            c = cc;
            k += 1;
        }
        i += 1;
    }
    sub_p(&[t[8], t[9], t[10], t[11], t[12], t[13], t[14], t[15], t[16]])
}

/// p256 0.13.2's own 32-bit file, verbatim but for the module wrapper: the
/// reference every operation above is tested against.
#[cfg(test)]
#[allow(dead_code, clippy::all)]
mod reference {
    use super::super::{MODULUS, R_2};
    use crate::arithmetic::util::{adc, mac, sbb};

    /// Raw field element.
    pub type Fe = [u32; 8];

    /// Translate a field element out of the Montgomery domain.
    #[inline]
    pub const fn fe_from_montgomery(w: &Fe) -> Fe {
        let w = fe32_to_fe64(w);
        montgomery_reduce(&[w[0], w[1], w[2], w[3], 0, 0, 0, 0])
    }

    /// Translate a field element into the Montgomery domain.
    #[inline]
    pub const fn fe_to_montgomery(w: &Fe) -> Fe {
        fe_mul(w, R_2.as_words())
    }

    /// Returns `a + b mod p`.
    pub const fn fe_add(a: &Fe, b: &Fe) -> Fe {
        let a = fe32_to_fe64(a);
        let b = fe32_to_fe64(b);

        // Bit 256 of p is set, so addition can result in five words.
        let (w0, carry) = adc(a[0], b[0], 0);
        let (w1, carry) = adc(a[1], b[1], carry);
        let (w2, carry) = adc(a[2], b[2], carry);
        let (w3, w4) = adc(a[3], b[3], carry);

        // Attempt to subtract the modulus, to ensure the result is in the field.
        let modulus = fe32_to_fe64(MODULUS.as_words());
        sub_inner(
            &[w0, w1, w2, w3, w4],
            &[modulus[0], modulus[1], modulus[2], modulus[3], 0],
        )
    }

    /// Returns `a - b mod p`.
    pub const fn fe_sub(a: &Fe, b: &Fe) -> Fe {
        let a = fe32_to_fe64(a);
        let b = fe32_to_fe64(b);
        sub_inner(&[a[0], a[1], a[2], a[3], 0], &[b[0], b[1], b[2], b[3], 0])
    }

    /// Returns `a * b mod p`.
    pub const fn fe_mul(a: &Fe, b: &Fe) -> Fe {
        let a = fe32_to_fe64(a);
        let b = fe32_to_fe64(b);

        let (w0, carry) = mac(0, a[0], b[0], 0);
        let (w1, carry) = mac(0, a[0], b[1], carry);
        let (w2, carry) = mac(0, a[0], b[2], carry);
        let (w3, w4) = mac(0, a[0], b[3], carry);

        let (w1, carry) = mac(w1, a[1], b[0], 0);
        let (w2, carry) = mac(w2, a[1], b[1], carry);
        let (w3, carry) = mac(w3, a[1], b[2], carry);
        let (w4, w5) = mac(w4, a[1], b[3], carry);

        let (w2, carry) = mac(w2, a[2], b[0], 0);
        let (w3, carry) = mac(w3, a[2], b[1], carry);
        let (w4, carry) = mac(w4, a[2], b[2], carry);
        let (w5, w6) = mac(w5, a[2], b[3], carry);

        let (w3, carry) = mac(w3, a[3], b[0], 0);
        let (w4, carry) = mac(w4, a[3], b[1], carry);
        let (w5, carry) = mac(w5, a[3], b[2], carry);
        let (w6, w7) = mac(w6, a[3], b[3], carry);

        montgomery_reduce(&[w0, w1, w2, w3, w4, w5, w6, w7])
    }

    /// Returns `-w mod p`.
    pub const fn fe_neg(w: &Fe) -> Fe {
        fe_sub(&[0; 8], w)
    }

    /// Returns `w * w mod p`.
    pub const fn fe_square(w: &Fe) -> Fe {
        fe_mul(w, w)
    }

    /// Montgomery Reduction
    ///
    /// The general algorithm is:
    /// ```text
    /// A <- input (2n b-limbs)
    /// for i in 0..n {
    ///     k <- A[i] p' mod b
    ///     A <- A + k p b^i
    /// }
    /// A <- A / b^n
    /// if A >= p {
    ///     A <- A - p
    /// }
    /// ```
    ///
    /// For secp256r1, we have the following simplifications:
    ///
    /// - `p'` is 1, so our multiplicand is simply the first limb of the intermediate A.
    ///
    /// - The first limb of p is 2^64 - 1; multiplications by this limb can be simplified
    ///   to a shift and subtraction:
    ///   ```text
    ///       a_i * (2^64 - 1) = a_i * 2^64 - a_i = (a_i << 64) - a_i
    ///   ```
    ///   However, because `p' = 1`, the first limb of p is multiplied by limb i of the
    ///   intermediate A and then immediately added to that same limb, so we simply
    ///   initialize the carry to limb i of the intermediate.
    ///
    /// - The third limb of p is zero, so we can ignore any multiplications by it and just
    ///   add the carry.
    ///
    /// References:
    /// - Handbook of Applied Cryptography, Chapter 14
    ///   Algorithm 14.32
    ///   http://cacr.uwaterloo.ca/hac/about/chap14.pdf
    ///
    /// - Efficient and Secure Elliptic Curve Cryptography Implementation of Curve P-256
    ///   Algorithm 7) Montgomery Word-by-Word Reduction
    ///   https://csrc.nist.gov/csrc/media/events/workshop-on-elliptic-curve-cryptography-standards/documents/papers/session6-adalier-mehmet.pdf
    #[inline]
    #[allow(clippy::too_many_arguments)]
    const fn montgomery_reduce(r: &[u64; 8]) -> Fe {
        let r0 = r[0];
        let r1 = r[1];
        let r2 = r[2];
        let r3 = r[3];
        let r4 = r[4];
        let r5 = r[5];
        let r6 = r[6];
        let r7 = r[7];
        let modulus = fe32_to_fe64(MODULUS.as_words());

        let (r1, carry) = mac(r1, r0, modulus[1], r0);
        let (r2, carry) = adc(r2, 0, carry);
        let (r3, carry) = mac(r3, r0, modulus[3], carry);
        let (r4, carry2) = adc(r4, 0, carry);

        let (r2, carry) = mac(r2, r1, modulus[1], r1);
        let (r3, carry) = adc(r3, 0, carry);
        let (r4, carry) = mac(r4, r1, modulus[3], carry);
        let (r5, carry2) = adc(r5, carry2, carry);

        let (r3, carry) = mac(r3, r2, modulus[1], r2);
        let (r4, carry) = adc(r4, 0, carry);
        let (r5, carry) = mac(r5, r2, modulus[3], carry);
        let (r6, carry2) = adc(r6, carry2, carry);

        let (r4, carry) = mac(r4, r3, modulus[1], r3);
        let (r5, carry) = adc(r5, 0, carry);
        let (r6, carry) = mac(r6, r3, modulus[3], carry);
        let (r7, r8) = adc(r7, carry2, carry);

        // Result may be within MODULUS of the correct value
        sub_inner(
            &[r4, r5, r6, r7, r8],
            &[modulus[0], modulus[1], modulus[2], modulus[3], 0],
        )
    }

    #[inline]
    #[allow(clippy::too_many_arguments)]
    const fn sub_inner(l: &[u64; 5], r: &[u64; 5]) -> Fe {
        let (w0, borrow) = sbb(l[0], r[0], 0);
        let (w1, borrow) = sbb(l[1], r[1], borrow);
        let (w2, borrow) = sbb(l[2], r[2], borrow);
        let (w3, borrow) = sbb(l[3], r[3], borrow);
        let (_, borrow) = sbb(l[4], r[4], borrow);

        // If underflow occurred on the final limb, borrow = 0xfff...fff, otherwise
        // borrow = 0x000...000. Thus, we use it as a mask to conditionally add the
        // modulus.
        let modulus = fe32_to_fe64(MODULUS.as_words());
        let (w0, carry) = adc(w0, modulus[0] & borrow, 0);
        let (w1, carry) = adc(w1, modulus[1] & borrow, carry);
        let (w2, carry) = adc(w2, modulus[2] & borrow, carry);
        let (w3, _) = adc(w3, modulus[3] & borrow, carry);

        [
            (w0 & 0xFFFFFFFF) as u32,
            (w0 >> 32) as u32,
            (w1 & 0xFFFFFFFF) as u32,
            (w1 >> 32) as u32,
            (w2 & 0xFFFFFFFF) as u32,
            (w2 >> 32) as u32,
            (w3 & 0xFFFFFFFF) as u32,
            (w3 >> 32) as u32,
        ]
    }

    // TODO(tarcieri): replace this with proper 32-bit arithmetic
    #[inline]
    const fn fe32_to_fe64(fe32: &Fe) -> [u64; 4] {
        [
            (fe32[0] as u64) | ((fe32[1] as u64) << 32),
            (fe32[2] as u64) | ((fe32[3] as u64) << 32),
            (fe32[4] as u64) | ((fe32[5] as u64) << 32),
            (fe32[6] as u64) | ((fe32[7] as u64) << 32),
        ]
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    const EDGES: [Fe; 6] = [
        [0; 8],
        [1, 0, 0, 0, 0, 0, 0, 0],
        [
            0xFFFF_FFFE,
            0xFFFF_FFFF,
            0xFFFF_FFFF,
            0,
            0,
            0,
            1,
            0xFFFF_FFFF,
        ], // p - 1
        [0, 0, 0, 0, 0, 0, 0, 0x8000_0000],
        [
            0xFFFF_FFFF,
            0xFFFF_FFFF,
            0xFFFF_FFFF,
            0xFFFF_FFFF,
            0xFFFF_FFFF,
            0xFFFF_FFFF,
            0,
            0xFFFF_FFFF,
        ],
        [
            0xFFFF_FFFF,
            0,
            0xFFFF_FFFF,
            0,
            0xFFFF_FFFF,
            0,
            0xFFFF_FFFF,
            0x7FFF_FFFF,
        ],
    ];

    #[test]
    fn the_limbs_are_the_modulus() {
        assert_eq!(&P, super::super::MODULUS.as_words());
    }

    #[test]
    fn edges_match_the_u64_reference() {
        for a in EDGES {
            assert_eq!(fe_neg(&a), reference::fe_neg(&a));
            assert_eq!(fe_square(&a), reference::fe_square(&a));
            assert_eq!(fe_to_montgomery(&a), reference::fe_to_montgomery(&a));
            assert_eq!(fe_from_montgomery(&a), reference::fe_from_montgomery(&a));
            for b in EDGES {
                assert_eq!(fe_add(&a, &b), reference::fe_add(&a, &b));
                assert_eq!(fe_sub(&a, &b), reference::fe_sub(&a, &b));
                assert_eq!(fe_mul(&a, &b), reference::fe_mul(&a, &b));
            }
        }
    }

    fn below_p() -> impl Strategy<Value = Fe> {
        // the top limb below 0xFFFF_FFFF keeps every value under p
        (any::<[u32; 7]>(), 0u32..0xFFFF_FFFF)
            .prop_map(|(lo, top)| [lo[0], lo[1], lo[2], lo[3], lo[4], lo[5], lo[6], top])
    }

    proptest! {
        #![proptest_config(ProptestConfig::with_cases(20_000))]
        #[test]
        fn ops_match_the_u64_reference(a in below_p(), b in below_p()) {
            prop_assert_eq!(fe_add(&a, &b), reference::fe_add(&a, &b));
            prop_assert_eq!(fe_sub(&a, &b), reference::fe_sub(&a, &b));
            prop_assert_eq!(fe_mul(&a, &b), reference::fe_mul(&a, &b));
            prop_assert_eq!(fe_square(&a), reference::fe_square(&a));
            prop_assert_eq!(fe_neg(&a), reference::fe_neg(&a));
            prop_assert_eq!(fe_to_montgomery(&a), reference::fe_to_montgomery(&a));
            prop_assert_eq!(fe_from_montgomery(&a), reference::fe_from_montgomery(&a));
        }
    }
}
